const byId = new Map(KEYS.map((k) => [k.id, k]))

export function keyById(id: string): KeyInfo | undefined {
  return byId.get(id)
}

/** Key by device key number 1..84. */
export function keyByNo(no: number): KeyInfo | undefined {
  return Number.isInteger(no) && no >= 1 && no <= KEYS.length ? KEYS[no - 1] : undefined
}

