function factorySlot(codes: number[]): Slot {
  return codes.length === 0 ? EMPTY_SLOT : Object.freeze({ kind: 'codes', codes: Object.freeze(codes) as number[] })
}

/**
 * Factory key map: the standard bank the device returns in Office mode, identical to the user's config.pro.
 * Frozen; use factoryTable() for a mutable copy.
 */
export const FACTORY: SlotTable = Object.freeze({
  base: Object.freeze(FACTORY_WIRE.base.map(factorySlot)) as Slot[],
  fn: Object.freeze(FACTORY_WIRE.fn.map(factorySlot)) as Slot[],
})

/** A mutable deep copy of FACTORY. */
export function factoryTable(): SlotTable {
  const copy = (s: Slot): Slot => (s.kind === 'codes' ? { kind: 'codes', codes: [...s.codes] } : s)
  return { base: FACTORY.base.map(copy), fn: FACTORY.fn.map(copy) }
}
